package handlers
import (
 "encoding/csv"
 "encoding/json"
 "net/http"
 "strings"
 "time"
 "fluxo/utils"
 "fluxo/services"
)
func(a *API)Metrics(w http.ResponseWriter,r *http.Request){if !manager(w,r){return};tasks,err:=a.filtered(r);if err!=nil{utils.DBError(w,err);return};active,done,late:=0,0,0;sectors:=map[string]map[string]any{};heat:=map[string]map[int]int{};duration:=map[string]float64{};counts:=map[string]int{};titles:=map[string]int{};stages:=map[string]int{};types:=map[string]int{};published:=0;for _,t:=range tasks{stages[t.Etapa]++;types[t.TipoConteudo]++;if t.Etapa=="publicado"{published++};if sectors[t.SetorID]==nil{sectors[t.SetorID]=map[string]any{"abertas":0,"concluidas":0}};titles[strings.ToLower(strings.TrimSpace(t.Titulo))]++;if heat[t.SetorID]==nil{heat[t.SetorID]=map[int]int{}};heat[t.SetorID][int(t.CriadoEm.Weekday())]++;if t.Status=="concluida"{done++;sectors[t.SetorID]["concluidas"]=sectors[t.SetorID]["concluidas"].(int)+1;if t.ConcluidoEm!=nil{duration[t.SetorID]+=t.ConcluidoEm.Sub(t.CriadoEm).Hours();counts[t.SetorID]++}}else{sectors[t.SetorID]["abertas"]=sectors[t.SetorID]["abertas"].(int)+1;if t.Status=="em_andamento"{active++};if services.IsLate(t,time.Now()){late++}}};for id,s:=range sectors{avg:=0.0;if counts[id]>0{avg=duration[id]/float64(counts[id])};s["tempo_medio_horas"]=avg};utils.JSON(w,200,map[string]any{"total":len(tasks),"em_andamento":active,"concluidas":done,"atrasadas":late,"setores":sectors,"heatmap_criacao":heat,"titulos_recorrentes":titles,"etapas":stages,"tipos_conteudo":types,"publicadas":published,"aguardando_aprovacao":stages["aprovacao"]})}
func safeCSV(value string)string{trimmed:=strings.TrimSpace(value);if strings.HasPrefix(trimmed,"=")||strings.HasPrefix(trimmed,"+")||strings.HasPrefix(trimmed,"-")||strings.HasPrefix(trimmed,"@")||strings.HasPrefix(value,"\t")||strings.HasPrefix(value,"\r")||strings.HasPrefix(value,"\n"){return "'"+value};return value}
func(a *API)Report(w http.ResponseWriter,r *http.Request){if !manager(w,r){return};tasks,err:=a.filtered(r);if err!=nil{utils.DBError(w,err);return};filters,_:=json.Marshal(r.URL.Query());if _,err=a.Repo.DB.Exec(r.Context(),"INSERT INTO relatorios(usuario_id,filtros,formato) VALUES($1,$2::jsonb,'csv')",User(r).ID,string(filters));err!=nil{utils.DBError(w,err);return};w.Header().Set("Content-Type","text/csv; charset=utf-8");w.Header().Set("Content-Disposition",`attachment; filename="fluxo-relatorio.csv"`);w.Header().Set("Cache-Control","no-store");w.Write([]byte{0xef,0xbb,0xbf});writer:=csv.NewWriter(w);writer.Comma=';';writer.Write([]string{"Código","Título","Setor ID","Responsável ID","Tipo","Etapa","Canal","Prioridade","Prazo da etapa","Prazo de entrega","Publicação prevista","Aprovador ID","Aprovado em","Link publicado","Criada em","Finalizada em"});for _,t:=range tasks{assigned:="";if t.ServidorID!=nil{assigned=*t.ServidorID};finished:="";if t.ConcluidoEm!=nil{finished=t.ConcluidoEm.Format(time.RFC3339)};writer.Write([]string{t.Codigo,safeCSV(t.Titulo),t.SetorID,assigned,t.TipoConteudo,t.Etapa,safeCSV(t.Canal),t.Prioridade,dateString(t.PrazoEtapa),t.Prazo.Format(time.RFC3339),dateString(t.PublicacaoPrevista),idString(t.AprovadorID),dateString(t.AprovadoEm),safeCSV(t.LinkPublicado),t.CriadoEm.Format(time.RFC3339),finished})};writer.Flush()}

func dateString(t *time.Time)string{if t==nil{return ""};return t.Format(time.RFC3339)}
func idString(id *string)string{if id==nil{return ""};return *id}
